// Resolve the checkout this run works in. With a managed worktree, the current
// directory is that worktree; otherwise it is the repoPath input.
const fs = await import('node:fs/promises');
const path = await import('node:path');
const { execFileSync } = await import('node:child_process');
const { createHash } = await import('node:crypto');
const i = input.run;
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim();
const workdir = await fs.realpath(process.cwd());
const top = await fs.realpath(git('rev-parse', '--show-toplevel'));
if (top !== workdir) throw new Error('The working directory must be the root of a Git checkout; its root is ' + top);
const baseCommit = git('rev-parse', '--verify', (i.baseRef || 'HEAD') + '^{commit}');
const branch = git('rev-parse', '--abbrev-ref', 'HEAD');
// A managed worktree's branch name always contains the run ID.
const dedicatedBranch = !!process.env.INTERLOCK_ROOT_RUN_ID && branch.includes(process.env.INTERLOCK_ROOT_RUN_ID);
const words = ((i.issue ? String(i.issue).split('/').pop() + ' ' : '') + i.request).toLowerCase()
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+/, '').slice(0, 40).replace(/-+$/, '') || 'change';
const taskDir = i.taskDir || path.join('.tasks', words + '-' + createHash('sha256').update(i.request).digest('hex').slice(0, 6));
if (path.isAbsolute(taskDir)) throw new Error('taskDir must be relative to the checkout');
await fs.mkdir(path.resolve(workdir, taskDir), { recursive: true });
const rel = path.relative(workdir, await fs.realpath(path.resolve(workdir, taskDir)));
if (!rel || rel.startsWith('..') || path.isAbsolute(rel)) throw new Error('taskDir must stay inside the checkout');
return {
  workdir, request: i.request, taskDir: rel, size: i.size ?? 'small', issue: i.issue ?? null, baseCommit, branch, dedicatedBranch,
  checkCommands: i.checkCommands ?? null, reviewPolicy: i.reviewPolicy ?? 'auto', createPr: i.createPr ?? false, commitArtifacts: i.commitArtifacts ?? false,
};

// Check the plan result, then decide how the plan is accepted.
const fs = await import('node:fs/promises');
const path = await import('node:path');
const { root, plan, spec, prior, changeReviewed } = input;
const inside = async (p) => {
  try {
    const file = await fs.realpath(path.resolve(root.workdir, p));
    const rel = path.relative(root.workdir, file);
    return !rel.startsWith('..') && !path.isAbsolute(rel) && (await fs.stat(file)).isFile();
  } catch { return false; }
};
const problems = [];
if (!(await inside(plan.artifactPath))) problems.push('plan.artifactPath ' + JSON.stringify(plan.artifactPath) + ' is not a file inside the checkout.');
if (root.size === 'standard' && !(spec && (await inside(spec.artifactPath)))) problems.push('spec.md is missing; write it in root.taskDir and keep its criteria ids.');
const commands = root.checkCommands ?? plan.checkCommands ?? [];
if (!root.checkCommands && commands.some((c) => /[`$;|&<>\n]/.test(c))) problems.push('Each check command must be one plain command without $, backticks, ;, |, &, < or >.');
// Bounded result repair: two corrections, then a person decides.
const repairs = prior?.route === 'repair' ? prior.repairs + 1 : 0;
const open = plan.decisions ?? [];
let route;
if (problems.length) route = repairs < 2 ? 'repair' : 'ask';
else if (open.length || root.reviewPolicy === 'always') route = 'ask';
else if (root.size === 'standard' && !changeReviewed) route = 'review';
else route = 'build';
const list = open.map((d, n) => (n + 1) + '. ' + d.question + '\n   Why it matters: ' + d.whyItMatters + '\n   Recommended: ' + d.recommendation).join('\n\n');
const question = problems.length ? 'The plan result is still incomplete after two corrections:\n' + problems.join('\n')
  : open.length ? 'The plan has decisions only you can settle. Approving accepts each recommendation.\n\n' + list
  : 'Approve this plan before any code is written?';
return {
  route, repairs: problems.length ? repairs : 0, problems, decisions: open, summary: plan.summary,
  feedback: problems.length ? 'Correct the plan result: ' + problems.join(' ') : '',
  question: question.slice(0, 4000),
  context: (plan.summary + '\n\nCheck commands Interlock will run after each build:\n' + (commands.join('\n') || '(none)')).slice(0, 32000),
};

// Route independent plan review: findings go to the spec or the plan; a third review with findings asks a person.
const { root, review, count } = input;
const material = review.findings.filter((f) => f.severity !== 'minor');
const owner = material.some((f) => f.owner === 'spec') && root.size === 'standard' ? 'spec' : 'plan';
const feedback = review.findings.map((f) => '[' + f.id + ' ' + f.severity + ', ' + f.owner + '] ' + f.location + ': ' + f.details + (f.recommendation ? ' Recommendation: ' + f.recommendation : '')).join('\n');
let route;
if (review.verdict === 'ready' && !material.length) route = root.reviewPolicy === 'always' ? 'ask' : 'build';
else if (review.verdict !== 'blocked' && material.length && count < 3) route = owner;
else route = 'ask';
const why = review.verdict === 'blocked' ? 'Independent plan review could not be completed: ' + review.limitations.join(' ')
  : material.length ? 'The plan still has review findings after ' + count + ' reviews.' : 'Independent review found the plan ready.';
return {
  route, summary: review.summary,
  feedback: material.length ? 'Independent plan review found problems. Resolve each by id and keep ids stable:\n' + feedback : '',
  question: (why + ' Approve the plan as it stands, request changes, or stop?').slice(0, 4000),
  context: (review.summary + (feedback ? '\n\nFindings:\n' + feedback : '')).slice(0, 32000),
};

// Capture the exact plan text a person approves.
const fs = await import('node:fs/promises');
const path = await import('node:path');
const { createHash } = await import('node:crypto');
const { root, plan, ask } = input;
let file = path.resolve(root.workdir, plan.artifactPath), text = '';
try { file = await fs.realpath(file); text = await fs.readFile(file, 'utf8'); } catch { text = ''; }
return {
  question: ask.question, context: ask.context, feedback: ask.feedback ?? '', file,
  revision: createHash('sha256').update(text).digest('hex'),
  evidence: !text ? '(The plan file could not be read.)' : text.length > 32000 ? text.slice(0, 31900) + '\n\n[Truncated; open ' + plan.artifactPath + ' for the rest.]' : text,
};

// Record a person's plan decision. Approval covers only the text they saw.
const fs = await import('node:fs/promises');
const { createHash } = await import('node:crypto');
const { answer, capture } = input;
const humanResponse = JSON.stringify(answer);
if (answer.choice === 'stop') return { route: 'stop', feedback: '', humanResponse, summary: 'A person stopped the change at plan approval.' };
if (answer.choice === 'revise') return { route: 'plan', humanResponse, summary: 'A person asked for plan changes.',
  feedback: 'A person reviewed the plan and asked for changes. Their words: ' + (answer.comment ?? '') + (capture.feedback ? '\n\nOutstanding findings:\n' + capture.feedback : '') };
let current = null;
try { current = createHash('sha256').update(await fs.readFile(capture.file, 'utf8')).digest('hex'); } catch { /* treated as changed */ }
if (current !== capture.revision) return { route: 'plan', humanResponse, summary: 'The plan changed after it was shown for approval.',
  feedback: 'The plan file changed or became unreadable after a person approved it. That approval does not cover the current text. Return the plan for approval again without further changes unless needed.' };
return { route: 'build', feedback: '', humanResponse, summary: 'A person approved the plan.' + (answer.comment ? ' Comment: ' + answer.comment : '') };

// Check the build result, then run the check commands at its commit.
// Bounded loops: two result corrections, three question rounds, one check repair.
const { execFileSync, spawnSync } = await import('node:child_process');
const { root, plan, spec, build, prior, review } = input;
const git = (...args) => execFileSync('git', args, { encoding: 'utf8', maxBuffer: 16 * 1024 * 1024, stdio: ['ignore', 'pipe', 'pipe'] }).trim();
const tryGit = (...args) => { try { return git(...args); } catch { return null; } };
const reset = prior?.route === 'ask';
const state = { repairs: 0, questions: reset ? 0 : prior?.questions ?? 0, checkFixes: 0 };
const packet = { workdir: root.workdir, request: root.request, size: root.size, taskDir: root.taskDir,
  planPath: plan.artifactPath, specPath: root.size === 'standard' ? spec?.artifactPath ?? null : null, baseCommit: root.baseCommit };
const out = (route, extra) => ({ route, ...state, ...packet, headCommit: null, changedFiles: [], diffStat: '', checks: [], checksPassed: null, checksNote: null,
  priorReview: review ?? null, feedback: '', question: '', context: '', evidence: '', revision: '', resume: 'build', kind: route, ...extra });
if (build.status === 'question') {
  state.questions++;
  const list = build.questions.map((q, n) => (n + 1) + '. ' + q.question + '\n   Why it matters: ' + q.whyItMatters + '\n   Recommended: ' + q.recommendation).join('\n\n');
  if (state.questions > 3) return out('ask', { kind: 'questions', question: 'The build has asked three rounds of questions. Let it continue with its recommendations, or stop?', context: build.summary, evidence: list, revision: String(state.questions) });
  return out('question', { question: ('The build needs a decision:\n\n' + list).slice(0, 4000), context: build.summary.slice(0, 32000) });
}
const problems = [];
const head = tryGit('rev-parse', '--verify', (build.headCommit || 'missing') + '^{commit}');
if (!head) problems.push('headCommit ' + JSON.stringify(build.headCommit) + ' is not a commit in the checkout.');
else {
  if (tryGit('merge-base', '--is-ancestor', root.baseCommit, head) === null) problems.push('headCommit does not descend from root.baseCommit ' + root.baseCommit + '.');
  else if (head === root.baseCommit) problems.push('headCommit equals root.baseCommit, so there is no change to review.');
  if (git('rev-parse', 'HEAD') !== head) problems.push('The checkout is not at headCommit; check out the commit you want reviewed.');
  if (git('status', '--porcelain', '--untracked-files=no') !== '') problems.push('Tracked files have uncommitted changes; commit or discard them.');
}
const ids = new Set((review?.findings ?? []).filter((f) => f.owner === 'build').map((f) => f.id));
const missing = [...ids].filter((id) => !build.resolutions.some((r) => r.id === id));
if (prior?.route !== 'build' && review?.route === 'build' && missing.length) problems.push('resolutions has no entry for finding ' + missing.join(', ') + '.');
if (problems.length) {
  state.repairs = prior?.route === 'build' && prior.kind === 'repair' ? prior.repairs + 1 : 1;
  const feedback = 'Your last result could not be used: ' + problems.join(' ');
  if (state.repairs > 2) return out('ask', { kind: 'repair', feedback, question: 'The build result is still unusable after two corrections. Let the builder try again, or stop?', context: build.summary, evidence: problems.join('\n'), revision: String(state.repairs) });
  return out('build', { kind: 'repair', feedback });
}
const changedFiles = git('diff', '--name-only', root.baseCommit, head).split('\n').filter(Boolean);
const commands = root.checkCommands ?? plan.checkCommands ?? [];
const checks = commands.map((command) => {
  const run = () => spawnSync(command, { shell: true, encoding: 'utf8', timeout: 900000, maxBuffer: 64 * 1024 * 1024, env: { ...process.env, CI: '1' } });
  let r = run(), attempts = 1, first = null;
  // A failure is retried once; a pass on the second attempt is reported as flaky.
  if (r.status !== 0 && !r.error) { first = ((r.stdout ?? '') + (r.stderr ?? '')).trim().slice(-1500); r = run(); attempts = 2; }
  const exitCode = typeof r.status === 'number' ? r.status : null;
  const tail = ((r.stdout ?? '') + (r.stderr ?? '')).trim().slice(-3000);
  return { command, exitCode, attempts, status: exitCode === 0 ? 'passed' : 'failed',
    output: (r.error ? r.error.message + '\n' : '') + (exitCode === 0 && first !== null ? 'Passed on the second attempt (flaky). First attempt:\n' + first : tail) };
});
const failed = checks.filter((c) => c.status === 'failed');
const facts = { headCommit: head, changedFiles: changedFiles.slice(0, 400), diffStat: git('diff', '--shortstat', root.baseCommit, head), checks,
  checksPassed: checks.length ? failed.length === 0 : null, checksNote: checks.length ? null : 'No check commands were set.' };
// The builder gets one chance to fix failing checks; after that reviewers decide who owns the failure.
if (failed.length && !(prior?.route === 'build' && prior.kind === 'checks')) {
  state.checkFixes = 1;
  return out('build', { ...facts, kind: 'checks', feedback: 'These check commands failed at ' + head + '. Fix them if the change caused them; otherwise say why in summary.\n\n' + failed.map((c) => '$ ' + c.command + ' (exit ' + c.exitCode + ')\n' + c.output).join('\n\n') });
}
return out('review', facts);

// Merge both reviews, apply the verdict rules and route findings to spec, plan or build.
const { root, verify, review, prior, grant } = input;
const lanes = [['specReview', 'S'], ['codeReview', 'C']];
const problems = [];
let findings = [];
for (const [key, prefix] of lanes) {
  const r = review[key];
  if (r.verdict !== 'blocked' && r.reviewedCommit !== verify.headCommit) problems.push(key + ' reviewed ' + JSON.stringify(r.reviewedCommit) + ' instead of ' + verify.headCommit + '.');
  findings.push(...r.findings.map((f) => ({ ...f, id: f.id.startsWith(prefix) ? f.id : prefix + '-' + f.id })));
}
const criteria = review.specReview.criteria;
if (review.specReview.verdict !== 'blocked' && !criteria.length) problems.push('specReview returned no criteria.');
const earlier = (verify.priorReview?.findings ?? []).filter((f) => f.severity !== 'minor' && f.owner !== 'environment').map((f) => f.id);
const resolutions = [...review.specReview.resolutions, ...review.codeReview.resolutions];
const unanswered = earlier.filter((id) => !resolutions.some((r) => r.id === id));
if (unanswered.length) problems.push('No resolutions entry for earlier finding ' + unanswered.join(', ') + '.');
// Environment findings never hold the change. Small changes have no spec, so spec findings go to the plan.
findings = findings.map((f) => f.owner === 'environment' ? { ...f, severity: 'minor' } : root.size === 'small' && f.owner === 'spec' ? { ...f, owner: 'plan' } : f);
const add = (id, details) => findings.push({ id, owner: 'build', severity: 'major', location: 'review rules', details });
if (verify.checksPassed === false) {
  const excused = findings.filter((f) => f.owner === 'environment').map((f) => f.location + ' ' + f.details).join('\n');
  const owned = verify.checks.filter((c) => c.status === 'failed' && !excused.includes(c.command)).map((c) => c.command);
  if (owned.length) add('R-checks', 'Check commands failed and no environment finding excuses them: ' + owned.join('; '));
}
const open = criteria.filter((c) => c.status !== 'verified').map((c) => c.id);
if (open.length && !findings.some((f) => f.severity !== 'minor')) add('R-criteria', 'Criteria not verified: ' + open.join(', '));
const stillOpen = resolutions.filter((r) => r.status === 'unresolved' && earlier.includes(r.id)).map((r) => r.id);
if (stillOpen.length && !findings.some((f) => stillOpen.includes(f.id))) add('R-resolutions', 'Earlier findings remain unresolved: ' + stillOpen.join(', '));
const material = findings.filter((f) => f.severity !== 'minor');
const blocked = lanes.some(([key]) => review[key].verdict === 'blocked');
// Bounded loops: one reviewer correction, three review rounds unless a person allows more.
const repairing = prior?.route === 'review' && prior.kind === 'format';
const round = (prior?.round ?? 0) + (repairing ? 0 : 1);
const until = grant?.kind === 'rounds' ? grant.until : 3;
const owner = ['spec', 'plan', 'build'].find((o) => material.some((f) => f.owner === o));
let route, kind = 'verdict';
if (problems.length && !blocked) { kind = 'format'; route = repairing ? 'ask' : 'review'; }
else if (blocked) { kind = 'blocked'; route = 'ask'; }
else if (!material.length) route = 'deliver';
else if (round >= until) { kind = 'rounds'; route = 'ask'; }
else route = owner;
const list = findings.map((f) => '[' + f.id + ' ' + f.severity + ', ' + f.owner + '] ' + f.location + ': ' + f.details).join('\n');
const summary = 'Criteria review: ' + review.specReview.summary + '\nCode review: ' + review.codeReview.summary;
const limitations = [...review.specReview.limitations, ...review.codeReview.limitations];
const deliveryNotes = [...review.specReview.deliveryNotes, ...review.codeReview.deliveryNotes];
const question = kind === 'format' ? 'The reviewers returned unusable results twice: ' + problems.join(' ') + ' Run the review again, or stop?'
  : kind === 'blocked' ? 'A reviewer could not complete the review. ' + limitations.join(' ') + ' Run the review again, or stop?'
  : 'The change still has findings after ' + round + ' review rounds. Allow three more rounds, or stop and keep the work as it is?';
const target = material.filter((f) => f.owner === owner);
return {
  route, kind, round, verdict: route === 'deliver' ? 'pass' : blocked ? 'blocked' : 'revise', summary,
  reviewedCommit: verify.headCommit, baseCommit: verify.baseCommit, checks: verify.checks, checksPassed: verify.checksPassed,
  criteria, findings, resolutions, deliveryNotes, limitations,
  formatFeedback: kind === 'format' ? 'Your previous review result was rejected: ' + problems.join(' ') : '',
  resume: kind === 'format' || kind === 'blocked' ? 'review' : owner ?? 'build',
  feedback: target.length ? 'Independent review found problems owned by ' + owner + '. Resolve each by id and keep ids stable:\n' + target.map((f) => '[' + f.id + ' ' + f.severity + '] ' + f.location + ': ' + f.details).join('\n') : '',
  question: question.slice(0, 4000),
  context: 'Continuing keeps the original requirements and the outstanding findings. It does not accept defects or authorize new scope.',
  evidence: (summary + '\n\n' + (list || 'No findings.')).slice(0, 32000), revision: verify.headCommit,
};

// One checkpoint for every exceeded limit: result corrections, question rounds, review rounds and blocked reviews.
const a = input.ask;
return { kind: a.kind, resume: a.resume, round: a.round ?? 0, feedback: a.feedback ?? '', question: a.question, context: a.context || 'A limit was reached.', evidence: a.evidence || a.feedback || '(none)', revision: String(a.revision || a.kind) };

const { asked, answer } = input;
const go = answer.choice === 'continue';
return {
  route: go ? asked.resume : 'stop', kind: asked.kind, until: asked.round + 3, humanResponse: JSON.stringify(answer),
  feedback: (asked.kind === 'questions' ? 'A person asked you to continue without further questions, using your recommended options. ' : 'A person allowed the workflow to continue past a limit. ')
    + (answer.comment ? 'Their words: ' + answer.comment + '\n' : '') + asked.feedback,
  summary: go ? 'A person allowed the workflow to continue (' + asked.kind + ').' : 'A person stopped the change (' + asked.kind + ').',
};

// Deliver only the commit that passed review.
const { execFileSync } = await import('node:child_process');
const git = (...args) => execFileSync('git', args, { encoding: 'utf8' }).trim();
const { root, review } = input;
if (review.verdict !== 'pass') throw new Error('Delivery requires a passing review');
const head = git('rev-parse', 'HEAD');
if (head !== review.reviewedCommit) throw new Error('The checkout is at ' + head + ' but review passed at ' + review.reviewedCommit + '. Review the new commit before delivery.');
return { route: root.createPr ? 'pr' : 'local', branch: git('rev-parse', '--abbrev-ref', 'HEAD'), reviewedCommit: head };

// Final result: verification (what was proven) and delivery (what was done with it) are reported separately.
const { root, review, deliver, pr } = input;
const blocked = root.createPr && !pr?.prUrl;
const open = review.findings.map(({ id, owner, severity, location, details }) => ({ id, owner, severity, location, details }));
return {
  outcome: 'finished', summary: pr?.summary ?? review.summary, taskDir: root.taskDir,
  verification: { status: 'passed', baseCommit: review.baseCommit, reviewedCommit: review.reviewedCommit, reviewRounds: review.round,
    checksPassed: review.checksPassed, checks: review.checks.map(({ command, status, exitCode, attempts }) => ({ command, status, exitCode, attempts })),
    criteria: review.criteria, openFindings: open,
    notes: [...(review.checksPassed === null ? ['No check commands ran.'] : []), ...review.checks.filter((c) => c.attempts > 1 && c.status === 'passed').map((c) => 'Flaky check passed on retry: ' + c.command), ...review.limitations] },
  delivery: { status: blocked ? 'blocked' : pr?.prUrl ? 'pr_opened' : 'local', branch: deliver.branch, prUrl: pr?.prUrl ?? null,
    ci: pr?.prUrl ? 'not_awaited' : 'not_applicable',
    notes: [...(blocked ? ['A pull request was requested but not opened. ' + (pr?.summary ?? '')] : []),
      ...(pr?.prUrl ? ["The pull request's own CI had not finished when this workflow ended."] : []),
      ...review.deliveryNotes] },
};

const { root, previous, review, build } = input;
const committed = build && build.headCommit ? ' Work so far is committed at ' + build.headCommit + '.' : ' No code was reviewed.';
return {
  outcome: 'stopped', summary: (previous.summary ?? 'A person stopped the change.') + committed, taskDir: root.taskDir,
  verification: { status: review ? 'incomplete' : 'not_reviewed', baseCommit: root.baseCommit, reviewedCommit: review?.reviewedCommit ?? null, reviewRounds: review?.round ?? 0,
    checksPassed: review?.checksPassed ?? null, checks: (review?.checks ?? []).map(({ command, status, exitCode, attempts }) => ({ command, status, exitCode, attempts })),
    criteria: review?.criteria ?? [], openFindings: (review?.findings ?? []).map(({ id, owner, severity, location, details }) => ({ id, owner, severity, location, details })),
    notes: ['Human decision: ' + (previous.humanResponse ?? 'stop')] },
  delivery: { status: 'not_attempted', branch: null, prUrl: null, ci: 'not_applicable', notes: [] },
};
